import { z } from 'zod';
import { ClientIdSchema, ServerIdSchema } from './ids.js';
import { TenantRoleSchema } from './permissions.js';

export const TenantSlugSchema = z
  .string()
  .trim()
  .toLowerCase()
  .min(3)
  .max(40)
  .regex(/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/, 'lowercase letters, numbers and dashes');

const Password = z.string().min(12, 'at least 12 characters').max(256);
const Email = z.string().trim().toLowerCase().email().max(254);

export const DeviceInfoSchema = z.object({
  /** Stable per installation; generated by the client and kept in IndexedDB. */
  deviceId: ClientIdSchema,
  name: z.string().trim().max(120).default('Unknown device'),
  platform: z.enum(['web', 'pwa', 'desktop', 'ios', 'android']).default('web'),
});

export const RegisterTenantRequestSchema = z.object({
  organizationName: z.string().trim().min(2).max(120),
  tenantSlug: TenantSlugSchema,
  ownerName: z.string().trim().min(1).max(120),
  ownerEmail: Email,
  password: Password,
  device: DeviceInfoSchema,
});
export type RegisterTenantRequest = z.input<typeof RegisterTenantRequestSchema>;

export const LoginRequestSchema = z.object({
  tenantSlug: TenantSlugSchema,
  email: Email,
  password: z.string().min(1).max(256),
  device: DeviceInfoSchema,
});
export type LoginRequest = z.input<typeof LoginRequestSchema>;

export const RefreshRequestSchema = z.object({
  refreshToken: z.string().min(20).max(512),
});

export const InviteMemberRequestSchema = z.object({
  email: Email,
  displayName: z.string().trim().min(1).max(120),
  role: TenantRoleSchema.exclude(['owner']),
  /** Initial password set by the admin; email invitations are planned. */
  temporaryPassword: Password,
});
export type InviteMemberRequest = z.input<typeof InviteMemberRequestSchema>;

export const UserSummarySchema = z.object({
  userId: ServerIdSchema,
  displayName: z.string(),
  email: z.string(),
  role: TenantRoleSchema,
  title: z.string().nullable(),
  status: z.enum(['active', 'deactivated']),
  /**
   * Profile photo: a path on the API (`/v1/avatars/<tenantId>/<key>`), resolve it against the
   * API base URL. The key changes with every new photo, so it can be cached forever.
   * null = no photo (show initials). Optional for older servers.
   */
  avatarUrl: z.string().nullable().optional(),
  department: z.string().nullable().optional(),
  phone: z.string().nullable().optional(),
  bio: z.string().nullable().optional(),
  /** IANA time zone, e.g. "Asia/Kolkata". */
  timeZone: z.string().nullable().optional(),
});
export type UserSummary = z.infer<typeof UserSummarySchema>;

const optionalText = (max: number) =>
  z
    .string()
    .trim()
    .max(max)
    .transform((v) => (v === '' ? null : v))
    .nullable()
    .optional();

/** PATCH /v1/me/profile. Omitted fields stay as they are; empty text or null clears a field. */
export const UpdateProfileRequestSchema = z
  .object({
    displayName: z.string().trim().min(1).max(80).optional(),
    title: optionalText(80),
    department: optionalText(80),
    phone: z
      .string()
      .trim()
      .max(32)
      .regex(/^[+()\d\s.-]*$/, 'Use digits, spaces and + ( ) - . only')
      .transform((v) => (v === '' ? null : v))
      .nullable()
      .optional(),
    bio: optionalText(500),
    timeZone: z
      .string()
      .trim()
      .max(64)
      .refine((v) => v === '' || isTimeZone(v), 'Unknown time zone')
      .transform((v) => (v === '' ? null : v))
      .nullable()
      .optional(),
  })
  .strict();
export type UpdateProfileRequest = z.input<typeof UpdateProfileRequestSchema>;

function isTimeZone(tz: string) {
  try {
    new Intl.DateTimeFormat('en', { timeZone: tz });
    return true;
  } catch {
    return false;
  }
}

/** Largest profile photo accepted (bytes, after base64 decoding). Clients crop to 512 px and compress first. */
export const MAX_AVATAR_BYTES = 160 * 1024;
/** PUT /v1/me/avatar: a cropped square PNG, JPEG or WebP as a data URL. */
export const SetAvatarRequestSchema = z.object({
  image: z
    .string()
    .max(Math.ceil((MAX_AVATAR_BYTES * 4) / 3) + 64)
    .regex(/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/, 'Use a PNG, JPEG or WebP image'),
});
export type SetAvatarRequest = z.input<typeof SetAvatarRequestSchema>;

export const SessionSchema = z.object({
  accessToken: z.string(),
  /** Seconds until the access token expires (short-lived, 15 min default). */
  accessTokenExpiresIn: z.number().int().positive(),
  refreshToken: z.string(),
  user: UserSummarySchema,
  tenant: z.object({ tenantId: ServerIdSchema, slug: z.string(), name: z.string() }),
  workspaceId: ServerIdSchema,
});
export type Session = z.infer<typeof SessionSchema>;

/** Claims inside the access JWT. tenantId comes only from here on the server. */
export interface AccessTokenClaims {
  sub: string; // userId
  tid: string; // tenantId
  sid: string; // device session id
  role: z.infer<typeof TenantRoleSchema>;
}

// ---------- Two-step verification (TOTP) ----------

/**
 * POST /v1/auth/login answers with this instead of a Session when the account has
 * two-step verification on. Finish with POST /v1/auth/mfa/verify within 5 minutes.
 */
export const MfaChallengeSchema = z.object({
  mfaRequired: z.literal(true),
  challengeId: z.string(),
  methods: z.array(z.enum(['totp', 'recovery'])),
  expiresAt: z.string(),
});
export type MfaChallenge = z.infer<typeof MfaChallengeSchema>;
export type LoginResponse = Session | MfaChallenge;
export const isMfaChallenge = (r: LoginResponse): r is MfaChallenge =>
  (r as MfaChallenge).mfaRequired === true;

export const MfaVerifyRequestSchema = z.object({
  challengeId: z.string().min(10).max(200),
  /** A 6-digit authenticator code, or a recovery code like `7f3k-9q2m`. */
  code: z.string().trim().min(6).max(20),
});

export const MfaStatusSchema = z.object({
  enabled: z.boolean(),
  enabledAt: z.string().nullable(),
  recoveryCodesLeft: z.number().int(),
  /** Setup started but not confirmed with a code yet. */
  pending: z.boolean(),
});
export type MfaStatus = z.infer<typeof MfaStatusSchema>;

export interface TotpSetup {
  /** Base32 secret for manual entry. */
  secret: string;
  /** `otpauth://` URL (what the QR code encodes). */
  otpauthUrl: string;
  /** The QR code as an SVG document, ready to show. */
  qrSvg: string;
}

export const MfaCodeRequestSchema = z.object({ code: z.string().trim().min(6).max(20) });
export const MfaDisableRequestSchema = z.object({
  password: z.string().min(1).max(256),
  code: z.string().trim().min(6).max(20),
});
export interface RecoveryCodes {
  recoveryCodes: string[];
}

/** GET /v1/auth/sso/:slug — what the login page offers for a workspace. */
export interface SsoInfo {
  enabled: boolean;
  /** Button text the admin chose. */
  label: string | null;
  /** False when the workspace is SSO-only (the owner can still use a password). */
  passwordLogin: boolean;
}

/**
 * POST /v1/auth/sso/exchange — swaps the one-time code from `#sso=` for the session.
 * Mobile apps (return URI `sampledge://…`) must also send the PKCE `codeVerifier` whose
 * S256 they passed as `codeChallenge` to `/v1/auth/sso/:slug/start`.
 */
export const SsoExchangeRequestSchema = z.object({
  code: z.string().min(10).max(200),
  codeVerifier: z
    .string()
    .regex(/^[A-Za-z0-9._~-]{43,128}$/)
    .optional(),
});
